-- 13_refresh_derived.sql  (Snowflake, v2)
-- Weakness #4: age and stale_member go out of date every day. Instead of rescanning the
-- whole base, touch only rows whose trigger date fell in (watermark, as_of]:
--   * age changes on the member's birthday          -> TO_CHAR(dob,'MMDD') in the window
--   * stale_member flips on last_flight_date + 91d  -> last_flight_date in [FLIP_FROM, FLIP_TO]
-- The predicate pieces are generated by derived.sql_window_vars() from the same Python
-- logic the unit tests prove equal to a full recompute (730 consecutive days, leap days,
-- missed-day gaps). The recompute is idempotent, so a superset window is always safe.
-- Template variables: ${TARGET_TABLE} ${AS_OF} ${STALE_DAYS} ${REFRESH_ALL}
--                     ${BIRTHDAY_FILTER} ${FLIP_FROM} ${FLIP_TO}
-- Run once per country table, then advance DERIVED_WATERMARK (the runner does both).
USE SCHEMA SKYPOINTS.CORE;

UPDATE ${TARGET_TABLE} t
   SET age          = CALC_AGE(t.dob, DATE '${AS_OF}'),
       stale_member = IS_STALE(t.last_flight_date, DATE '${AS_OF}', ${STALE_DAYS}),
       as_of_date   = DATE '${AS_OF}'
 WHERE ${REFRESH_ALL}
    OR (t.dob IS NOT NULL AND ${BIRTHDAY_FILTER})
    OR (t.last_flight_date BETWEEN DATE '${FLIP_FROM}' AND DATE '${FLIP_TO}');
